const payload = $input.first().json;
const body = payload.body && typeof payload.body === 'object' ? payload.body : payload;
const event = String(body.event || '');
const messageType = body.message_type;
const isIncoming = messageType === 'incoming' || messageType === 0;
const isPrivate = Boolean(body.private);
const status = String(body.conversation?.status || '');
const content = String(body.content || '').trim();
const senderType = String(body.sender?.type || '');
const meta = body.conversation?.meta || {};
const assigneeType = String(meta.assignee_type || meta.assignee?.type || '').toLowerCase().replace(/_/g, '');
const botAssigned = assigneeType.includes('agentbot');
const handoffPattern = /asesor|persona|humano|agente|soporte|hablar con alguien|atenci[oó]n humana|reclamo|queja|gerente|ayuda humana/i;
const wantsHuman = handoffPattern.test(content);
const botMayReply = status === 'pending' || (status === 'open' && botAssigned);
const shouldReply =
  event === 'message_created' &&
  isIncoming &&
  !isPrivate &&
  botMayReply &&
  Boolean(content) &&
  senderType !== 'agent_bot' &&
  senderType !== 'user';

return [{
  json: {
    shouldReply,
    wantsHuman,
    content,
    accountId: body.account?.id,
    conversationId: body.conversation?.id,
    contactName: body.sender?.name || 'Cliente',
    event,
    status,
    messageType,
    senderType,
    assigneeType,
  },
}];

const event = $input.first().json;
const panel = $env.CHATWOOT_PUBLIC_URL || 'http://localhost:3000';
return [{
  json: {
    ...event,
    reply: 'Te conecto con un asesor de iShop. Sigue en este mismo chat: en un momento te escribe una persona.',
    privateNote: `Handoff de ${event.contactName}. Atiéndelo en ${panel} > Conversaciones > iShop Web. Para devolverlo a la IA, cambia el estado a Pendiente.`,
    wantsHuman: true,
  },
}];

const event = $('Preparar evento').first().json;
const current = $input.first().json;
const raw = String(current.output || current.text || '').trim();
const wantsHuman = raw.includes('[[HANDOFF]]') || Boolean(event.wantsHuman) || Boolean(current.wantsHuman);
const reply = raw.replace(/\[\[HANDOFF\]\]/g, '').trim() || 'Te conecto con un asesor humano. Seguiremos en esta misma conversación.';
return [{ json: { ...event, reply, wantsHuman, privateNote: `Handoff solicitado por ${event.contactName}. La IA dejó de responder. Para devolverla a la IA, cambia el estado a Pending.` } }];

const event = $('Preparar evento').first().json;
const current = $input.first().json;
const token = $env.CHATWOOT_BOT_TOKEN;
const admin = $env.CHATWOOT_ACCESS_TOKEN || token;
if (!token) {
  throw new Error('Falta CHATWOOT_BOT_TOKEN');
}
const base = `http://chatwoot:3000/api/v1/accounts/${event.accountId}/conversations/${event.conversationId}`;
const headers = {
  api_access_token: token,
  'Content-Type': 'application/json',
};
const adminHeaders = {
  api_access_token: admin,
  'Content-Type': 'application/json',
};
try {
  await this.helpers.httpRequest({
    method: 'POST',
    url: `${base}/toggle_typing_status`,
    headers,
    body: { typing_status: 'off', is_private: false },
  });
} catch (error) {}
const reply = current.reply || 'Estoy revisando la información de iShop.';
const sent = await this.helpers.httpRequest({
  method: 'POST',
  url: `${base}/messages`,
  headers,
  body: {
    content: reply,
    message_type: 'outgoing',
    private: false,
  },
});
if (current.wantsHuman) {
  await this.helpers.httpRequest({
    method: 'POST',
    url: `${base}/toggle_status`,
    headers,
    body: { status: 'open' },
  });
  let assigneeId = 2;
  try {
    const agentsRes = await this.helpers.httpRequest({
      method: 'GET',
      url: `http://chatwoot:3000/api/v1/accounts/${event.accountId}/agents`,
      headers: adminHeaders,
    });
    const agents = Array.isArray(agentsRes) ? agentsRes : (agentsRes.payload || []);
    const preferido = String($env.CHATWOOT_HUMAN_AGENT_EMAIL || '').trim().toLowerCase();
    const human = (preferido && agents.find((agent) => String(agent.email || '').toLowerCase() === preferido))
      || agents.find((agent) => agent.role === 'administrator')
      || agents.find((agent) => agent.role === 'agent');
    if (human?.id) {
      assigneeId = human.id;
    }
  } catch (error) {}
  try {
    await this.helpers.httpRequest({
      method: 'POST',
      url: `${base}/assignments`,
      headers: adminHeaders,
      body: { assignee_id: assigneeId },
    });
  } catch (error) {}
  await this.helpers.httpRequest({
    method: 'POST',
    url: `${base}/messages`,
    headers,
    body: {
      content: current.privateNote || `Handoff solicitado por ${event.contactName}. Responde desde http://localhost:3000 en la bandeja iShop Web.`,
      message_type: 'outgoing',
      private: true,
    },
  });
}
return [{ json: { ok: true, reply, sentId: sent.id || sent.payload?.id, wantsHuman: Boolean(current.wantsHuman) } }];

const event = $input.first().json;
const token = $env.CHATWOOT_BOT_TOKEN;
if (token && event.accountId && event.conversationId) {
  try {
    await this.helpers.httpRequest({
      method: 'POST',
      url: `http://chatwoot:3000/api/v1/accounts/${event.accountId}/conversations/${event.conversationId}/toggle_typing_status`,
      headers: {
        api_access_token: token,
        'Content-Type': 'application/json',
      },
      body: { typing_status: 'on', is_private: false },
    });
  } catch (error) {}
}
return [{ json: event }];

const event = $input.first().json;
const content = String(event.content || '').trim();
const normalized = (value) => String(value || '')
  .normalize('NFD')
  .replace(/[\u0300-\u036f]/g, '')
  .toLowerCase()
  .replace(/\s+/g, ' ')
  .trim();
const current = normalized(content);

let fastReply = '';
if (/^(hola|holi|buenas|buenos dias|buenas tardes|buenas noches|hey|hello|que tal)[!?. ]*$/.test(current)) {
  fastReply = '¡Hola! Soy el asistente de iShop. Puedo ayudarte a encontrar productos, comparar opciones, revisar precios, envíos, pagos o garantías. ¿Qué necesitas?';
} else if (/^(gracias|muchas gracias|perfecto|listo|ok|okay|vale)[!?. ]*$/.test(current)) {
  fastReply = '¡Con gusto! Si necesitas algo más de iShop, aquí estoy.';
}

let conversationTurns = [];
if (!fastReply) {
  try {
    const history = await this.helpers.httpRequest({
      method: 'GET',
      url: `http://chatwoot:3000/api/v1/accounts/${event.accountId}/conversations/${event.conversationId}/messages`,
      headers: { api_access_token: $env.CHATWOOT_ACCESS_TOKEN || $env.CHATWOOT_BOT_TOKEN },
      timeout: 5000,
    });
    const messages = Array.isArray(history?.payload) ? history.payload : [];
    conversationTurns = messages
      .filter((message) => !message.private && (message.message_type === 0 || message.message_type === 1))
      .sort((a, b) => Number(a.created_at || 0) - Number(b.created_at || 0))
      .slice(-12)
      .map((message) => ({
        role: message.message_type === 0 ? 'Cliente' : 'Asistente',
        content: String(message.content || '').trim(),
      }))
      .filter((turn) => turn.content);
  } catch (error) {}
  const lastTurn = conversationTurns[conversationTurns.length - 1];
  if (!lastTurn || lastTurn.role !== 'Cliente' || normalized(lastTurn.content) !== current) {
    conversationTurns.push({ role: 'Cliente', content });
  }
  conversationTurns = conversationTurns.slice(-12);
}

const conversationText = conversationTurns
  .map((turn) => `${turn.role}: ${turn.content}`)
  .join('\n');
return [{ json: { ...event, fastReply, conversationText } }];

const event = $input.first().json;
const systemText = [
  'Eres el módulo de comprensión del asistente de iShop Ecuador.',
  'Analiza el ÚLTIMO mensaje del Cliente usando el historial solo como contexto.',
  'Si cambia de tema, el tema nuevo manda. Corrige errores: microfno=micrófono, relok=reloj, mackbook=MacBook.',
  'Devuelve exclusivamente JSON válido con estas claves:',
  '"intent": product_search | compare | details | purchase | information | handoff | smalltalk | unclear.',
  '"search_query": búsqueda breve y corregida para una base vectorial. Laptop Apple debe buscarse como MacBook y reloj Apple como Apple Watch.',
  '"category": macbook | iphone | ipad | watch | airpods | mac_desktop | audio | accessory | "".',
  '"budget": número en dólares vigente para el producto actual o null.',
  '"in_catalog": false si claramente no es un producto vendido por una tienda Apple (micrófono, impresora, consola, laptop Windows); true si sí; null si no sabes.',
  '"information_topic": shipping | payments | warranty | service | stores | contact | corporate | "".',
  '"refers_previous": true si menciona opción 1/2/3, ese/esa, anteriores o pide comparar lo recién mostrado.',
  '"clarifying_question": pregunta breve solo si realmente no se entiende; de lo contrario "".',
].join('\n');
const userText = [
  'Conversación reciente de Chatwoot:',
  event.conversationText || `Cliente: ${event.content}`,
  '',
  'Interpreta únicamente el último mensaje del Cliente.',
].join('\n');
const geminiBody = {
  system_instruction: { parts: [{ text: systemText }] },
  contents: [{ role: 'user', parts: [{ text: userText }] }],
  generationConfig: {
    maxOutputTokens: 900,
    temperature: 0.1,
    responseMimeType: 'application/json',
    thinkingConfig: { thinkingLevel: 'low' },
  },
};
return [{ json: { ...event, geminiBody } }];

const event = $('Preparar contexto RAG').first().json;
const response = $input.first().json;
const normalize = (value) => String(value || '')
  .normalize('NFD')
  .replace(/[\u0300-\u036f]/g, '')
  .toLowerCase()
  .replace(/\s+/g, ' ')
  .trim();
const current = normalize(event.content);
const categories = new Set(['macbook', 'iphone', 'ipad', 'watch', 'airpods', 'mac_desktop', 'audio', 'accessory']);

const heuristic = () => {
  let corrected = String(event.content || '')
    .replace(/\bmicrofno\b/gi, 'micrófono')
    .replace(/\brelok\b|\brelo\b/gi, 'reloj Apple Watch')
    .replace(/\bmackbook\b/gi, 'MacBook');
  let category = '';
  if (/\b(adaptador|cable|cargador|case|funda|teclado|mouse|correa|protector|mochila|airtag|pencil)\b/.test(current)) {
    category = 'accessory';
  } else if (/\b(macbook|laptop|portatil|notebook)\b/.test(current)) {
    category = 'macbook';
    corrected = corrected.replace(/\b(laptop|portatil|notebook)\b/gi, 'MacBook');
  } else if (/\b(iphone|celular|telefono)\b/.test(current)) category = 'iphone';
  else if (/\b(ipad|tablet)\b/.test(current)) category = 'ipad';
  else if (/\b(apple watch|relo[jk])\b/.test(current)) category = 'watch';
  else if (/\bairpods?\b/.test(current)) category = 'airpods';
  else if (/\b(imac|mac mini|mac studio)\b/.test(current)) category = 'mac_desktop';
  else if (/\b(audifonos?|auriculares?|parlante|bocina|bose|jbl|beats)\b/.test(current)) category = 'audio';

  let information_topic = '';
  if (/\b(envio|entrega|domicilio)\b/.test(current)) information_topic = 'shipping';
  else if (/\b(pago|tarjeta|cuota|diferido)\b/.test(current)) information_topic = 'payments';
  else if (/\b(garantia|devolucion|cambio)\b/.test(current)) information_topic = 'warranty';
  else if (/\b(servicio tecnico|reparacion|reparar)\b/.test(current)) information_topic = 'service';
  else if (/\b(tienda|local|sucursal)\b/.test(current)) information_topic = 'stores';
  else if (/\b(contacto|telefono|correo)\b/.test(current)) information_topic = 'contact';
  else if (/\b(corporativ|empresa)\b/.test(current)) information_topic = 'corporate';

  let intent = information_topic ? 'information' : 'product_search';
  if (/\b(compar\w*|diferencias?|opcion 1|opcion 2|versus|vs|contra)\b/.test(current)) intent = 'compare';
  else if (/\b(comprar|lo quiero|me lo llevo|como compro|quiero ese|quiero esa)\b/.test(current)) intent = 'purchase';
  else if (/\b(detalles?|especificaciones|caracteristicas|que trae|que incluye)\b/.test(current)) intent = 'details';

  const budgetMatch = current.match(/(?:presupuesto|tengo|hasta|maximo)\D{0,12}(\d{2,5})\b/) || current.match(/\$\s*(\d{2,5})\b/);
  const unsupported = /\b(microfono|microfno|impresora|playstation|xbox|consola|laptop windows|computadora windows)\b/.test(current);
  return {
    intent,
    search_query: corrected,
    category,
    budget: budgetMatch ? Number(budgetMatch[1]) : null,
    in_catalog: unsupported ? false : (category ? true : null),
    information_topic,
    refers_previous: /\b(opcion(es)?|primera|segunda|tercera|esa|ese|esas|esos|anterior(es)?|las dos|los dos)\b/.test(current),
    clarifying_question: '',
    source: 'heuristic',
  };
};

let understanding;
try {
  const parts = response?.candidates?.[0]?.content?.parts || [];
  const raw = parts.filter((part) => part.text && !part.thought).map((part) => part.text).join('').trim();
  understanding = JSON.parse(raw.replace(/^```json\s*|```$/g, '').trim());
  understanding.source = 'gemini';
} catch (error) {
  understanding = heuristic();
  understanding.geminiError = response?.error?.message || error.message;
}

understanding.intent = String(understanding.intent || 'unclear');
understanding.category = categories.has(understanding.category) ? understanding.category : '';
understanding.search_query = String(understanding.search_query || event.content).trim() || event.content;
understanding.budget = understanding.budget === null || understanding.budget === undefined || understanding.budget === ''
  ? null
  : Number(understanding.budget);
if (!Number.isFinite(understanding.budget)) understanding.budget = null;
understanding.refers_previous = Boolean(understanding.refers_previous);

if (understanding.intent === 'handoff') {
  return [{ json: { ...event, understanding, skipRag: true, output: 'Te conecto con un asesor de iShop. Sigue en este mismo chat: en un momento te escribe una persona.\n[[HANDOFF]]' } }];
}
if (understanding.intent === 'smalltalk') {
  return [{ json: { ...event, understanding, skipRag: true, output: 'Puedo ayudarte con productos Apple, comparaciones, precios, envíos, pagos o garantías de iShop. ¿Qué buscas?' } }];
}
if (understanding.intent === 'unclear') {
  return [{ json: { ...event, understanding, skipRag: true, output: understanding.clarifying_question || 'Cuéntame qué producto buscas o qué duda tienes sobre compras, envíos, pagos o garantías de iShop.' } }];
}
if (understanding.in_catalog === false) {
  return [{ json: {
    ...event,
    understanding,
    skipRag: true,
    output: `No encontré “${understanding.search_query}” como producto en el catálogo actual de iShop. Puedo ayudarte con Mac, iPhone, iPad, Apple Watch, AirPods, audio y accesorios, o conectarte con un asesor.`,
  } }];
}

const isInformation = understanding.intent === 'information' || Boolean(understanding.information_topic);
const must = [{ key: 'doc_kind', match: { value: isInformation ? 'information' : 'product' } }];
const urls = [...new Set(String(event.conversationText || '').match(/https:\/\/ec\.tiendasishop\.com\/products\/[a-z0-9\-]+/gi) || [])];
if (!isInformation && understanding.refers_previous && urls.length) {
  must.push({ key: 'url', match: { any: urls.slice(-3) } });
} else if (!isInformation && understanding.category) {
  must.push({ key: 'category', match: { value: understanding.category } });
}
return [{ json: {
  ...event,
  understanding,
  skipRag: false,
  searchQuery: understanding.search_query,
  qdrantFilter: { must },
  isInformation,
} }];

const context = $('Interpretar intención').first().json;
const understanding = context.understanding || {};
const normalize = (value) => String(value || '')
  .normalize('NFD')
  .replace(/[\u0300-\u036f]/g, '')
  .toLowerCase();
const rows = $input.all().map((item) => item.json);
const documents = rows.map((row) => ({
  content: String(row.document?.pageContent || ''),
  score: Number(row.score || 0),
})).filter((document) => document.content);

if (context.isInformation) {
  if (!documents.length) {
    return [{ json: { ...context, output: 'No encontré información suficiente en la base pública de iShop. Puedes reformular la pregunta o escribir “quiero un asesor”.' } }];
  }
  const queryWords = normalize(context.searchQuery).split(/[^a-z0-9]+/).filter((word) => word.length > 3);
  const sentences = documents
    .map((document) => document.content)
    .join('\n')
    .split(/(?<=[.!?])\s+|\n+/)
    .map((sentence) => sentence.trim())
    .filter((sentence) => sentence && queryWords.some((word) => normalize(sentence).includes(word)));
  const output = [...new Set(sentences)].slice(0, 6).join(' ').slice(0, 1200)
    || documents[0].content.slice(0, 1200);
  return [{ json: { ...context, output } }];
}

// Un documento cargado por un asesor puede tratar temas que el clasificador
// todavía no conoce, y la pregunta se interpreta como búsqueda de producto. Si
// la evidencia de producto es floja y el mensaje es una pregunta, se reintenta
// sobre los documentos informativos antes de responder con el catálogo.
const mejorPuntaje = documents.length ? Math.max(...documents.map((documento) => documento.score)) : 0;
const esPregunta = /^(puedo|como|que pasa|cual|cuanto|cuando|donde|hay|tienen|se puede|existe|aceptan|cobran)\b/.test(normalize(context.content));
if (mejorPuntaje < 0.7 && esPregunta) {
  try {
    const vectores = await this.helpers.httpRequest({
      method: 'POST',
      url: 'http://ollama:11434/api/embed',
      body: { model: 'nomic-embed-text:latest', input: [context.searchQuery || context.content], keep_alive: -1 },
      json: true,
      timeout: 60000,
    });
    const busqueda = await this.helpers.httpRequest({
      method: 'POST',
      url: 'http://qdrant:6333/collections/ishop_rag_v2/points/search',
      body: {
        vector: vectores.embeddings[0],
        limit: 6,
        with_payload: true,
        filter: { must: [{ key: 'doc_kind', match: { value: 'information' } }] },
      },
      json: true,
      timeout: 60000,
    });
    const informativos = (busqueda.result || []).filter((punto) => punto.score > mejorPuntaje + 0.05);
    if (informativos.length) {
      const texto = informativos.slice(0, 3).map((punto) => punto.payload.content).join('\n').slice(0, 1200);
      return [{ json: { ...context, isInformation: true, output: texto } }];
    }
  } catch (error) {}
}

const field = (content, label) => {
  const match = content.match(new RegExp(`^${label}:\\s*(.+)$`, 'mi'));
  return match ? match[1].trim() : '';
};
const products = documents.map((document) => {
  const content = document.content;
  const variantsMatch = content.match(/Variantes disponibles:\s*([\s\S]*?)\nDescripción:/i);
  return {
    title: field(content, 'Producto'),
    url: field(content, 'URL'),
    type: field(content, 'Tipo'),
    price: Number((field(content, 'Precio desde').match(/[\d.]+/) || [0])[0]),
    variants: variantsMatch ? variantsMatch[1].trim() : '',
    description: field(content, 'Descripción'),
    score: document.score,
  };
}).filter((product) => product.title && product.url && product.price > 0);

const queryWords = normalize(context.searchQuery).split(/[^a-z0-9]+/).filter((word) => word.length > 2);
products.forEach((product) => {
  const title = normalize(product.title);
  product.rank = product.score * 10 + queryWords.filter((word) => title.includes(word)).length * 2;
});
let ranked = [...products];
const budget = understanding.budget;
const previousUrls = [...new Set(String(context.conversationText || '').match(/https:\/\/ec\.tiendasishop\.com\/products\/[a-z0-9\-]+/gi) || [])].slice(-3);
if (understanding.refers_previous && previousUrls.length) {
  ranked.sort((a, b) => previousUrls.indexOf(a.url) - previousUrls.indexOf(b.url));
} else if (budget !== null && budget !== undefined) {
  const within = ranked.filter((product) => product.price <= budget).sort((a, b) => b.rank - a.rank);
  const above = ranked.filter((product) => product.price > budget).sort((a, b) => a.price - b.price || b.rank - a.rank);
  ranked = [...within, ...above];
} else {
  ranked.sort((a, b) => b.rank - a.rank);
}
ranked = ranked.slice(0, 3);

if (!ranked.length || (!understanding.category && !understanding.refers_previous && ranked[0].score < 0.6)) {
  return [{ json: {
    ...context,
    output: `No encontré “${understanding.search_query || context.content}” como producto en el catálogo actual de iShop. Puedes reformular la búsqueda o escribir “quiero un asesor”.`,
  } }];
}

if (understanding.intent === 'compare' && ranked.length >= 2) {
  const [first, second] = ranked;
  const firstVariant = first.variants.split('\n')[0] || 'Características no detalladas en la ficha';
  const secondVariant = second.variants.split('\n')[0] || 'Características no detalladas en la ficha';
  const difference = Math.abs(first.price - second.price);
  let recommendation = first.price <= second.price
    ? `${first.title} cuesta $${Math.round(difference)} menos.`
    : `${second.title} cuesta $${Math.round(difference)} menos.`;
  if (budget !== null && budget !== undefined) {
    const inside = [first, second].filter((product) => product.price <= budget);
    recommendation = inside.length
      ? `Para tu presupuesto de $${budget}, recomiendo ${inside.sort((a, b) => b.rank - a.rank)[0].title}.`
      : `Ninguna entra en tu presupuesto de $${budget}; la más cercana es ${[first, second].sort((a, b) => a.price - b.price)[0].title}.`;
  }
  const output = [
    'Comparación entre las opciones 1 y 2:',
    '',
    `1. ${first.title} — desde $${Math.round(first.price)}`,
    `   ${firstVariant}`,
    `   ${first.url}`,
    `2. ${second.title} — desde $${Math.round(second.price)}`,
    `   ${secondVariant}`,
    `   ${second.url}`,
    '',
    recommendation,
    'Los precios y la disponibilidad pueden cambiar.',
  ].join('\n');
  return [{ json: { ...context, output } }];
}

if (understanding.intent === 'purchase' && ranked.length) {
  const product = ranked[0];
  return [{ json: {
    ...context,
    output: `${product.title} está publicado desde $${Math.round(product.price)}.\n\nVer producto y comprar:\n${product.url}\n\nLa compra y el pago se completan en la ficha. Los precios y la disponibilidad pueden cambiar.`,
  } }];
}

if (understanding.intent === 'details' && ranked.length) {
  const product = ranked[0];
  const variants = product.variants.split('\n').slice(0, 3).join('\n');
  return [{ json: {
    ...context,
    output: `${product.title} — desde $${Math.round(product.price)}\n\n${product.description || 'La ficha no detalla una descripción adicional.'}${variants ? `\n\nVariantes:\n${variants}` : ''}\n\n${product.url}\n\nLos precios y la disponibilidad pueden cambiar.`,
  } }];
}

const list = ranked.map((product) => {
  const over = budget !== null && budget !== undefined && product.price > budget ? ' (supera tu presupuesto)' : '';
  return `• ${product.title} — desde $${Math.round(product.price)}${over}\n  ${product.url}`;
}).join('\n');
let intro = 'Estas son las opciones más relacionadas del catálogo actual:';
if (budget !== null && budget !== undefined) {
  const inside = ranked.filter((product) => product.price <= budget);
  intro = inside.length
    ? `Con tu presupuesto de $${budget}, estas son las opciones que mejor encajan:`
    : `No encontré una opción dentro de tu presupuesto de $${budget}. Las más cercanas son:`;
}
return [{ json: { ...context, output: `${intro}\n\n${list}\n\nLos precios y la disponibilidad pueden cambiar; confírmalos en la ficha.` } }];

